ALTER AGENT HACKATHON_D2K_PREWORK.L2P_CONSUMER.L2P_CONSUMER MODIFY LIVE VERSION SET SPECIFICATION = $${"models": {"orchestration": "claude-opus-5-5"}, "orchestration": {"budget": {"seconds": 120, "tokens": 30000}}, "instructions": {"response": "State the product, version and queried object you used. Present an account-review shortlist ranked by computed invoiced sales excluding tax, with no currency symbol. Clearly state the evidence boundary: the product has no consent, campaign response, margin or causal-uplift data, so you cannot claim campaign effects, eligibility to contact, or profitability. Never perform or offer to perform actions. State that recorded contract results and current release integrity were checked; do not claim all source checks were rerun. Identify the semantic view and returned release version. Show query-derived facts only.", "orchestration": "You are the analyst for SYNTHETIC Northstar Supply. For each data question call DiscoverReleasedProduct then VerifyReleasedContract. If unavailable or ok=false, STOP and show the failure, never estimate. Use ReleasedSalesAnalyst for sales questions, rankings, date filtering and aggregations through DAILY_SALES_SEMANTIC only. Include release_version with requested dimensions in queries. Empty guarded results mean unavailable/stale, NOT zero sales. Never query RAW, candidates, registry tables or arbitrary objects through Analyst. The bounded RankCustomersBySales and CustomerSalesDetail tools are fallback checks, not the default analytical path. Before displaying results call VerifyReleasedContract again; if its release version differs from the query result or ok=false, withhold the answer and ask to retry. You cannot build, validate, publish or release products, send campaigns, schedule anything or contact customers. Explain unsupported consent/margin/uplift limits without inventing facts."}, "tools": [{"tool_spec": {"type": "generic", "name": "DiscoverReleasedProduct", "description": "Return the currently released L2P product (version, object, fields, not-available data) or available=false.", "input_schema": {"type": "object", "properties": {}}}}, {"tool_spec": {"type": "generic", "name": "RankCustomersBySales", "description": "Rank customers by SUM(SALES_EXCLUDING_TAX) from the current release. TOP_N 1-20. Optional START_DATE/END_DATE as YYYY-MM-DD or empty string.", "input_schema": {"type": "object", "properties": {"TOP_N": {"type": "number", "description": "Number of customers 1-20"}, "START_DATE": {"type": "string", "description": "Inclusive start date YYYY-MM-DD or empty"}, "END_DATE": {"type": "string", "description": "Inclusive end date YYYY-MM-DD or empty"}}, "required": ["TOP_N", "START_DATE", "END_DATE"]}}}, {"tool_spec": {"type": "generic", "name": "CustomerSalesDetail", "description": "Daily item-level released sales rows for one CUSTOMER_ID from the current release.", "input_schema": {"type": "object", "properties": {"CUSTOMER_ID": {"type": "number", "description": "Customer ID from the ranking"}}, "required": ["CUSTOMER_ID"]}}}, {"tool_spec": {"type": "generic", "name": "VerifyReleasedContract", "description": "Verify current release identity, recorded 11 contract checks and current content hash before displaying data. Not a rerun of source validation.", "input_schema": {"type": "object", "properties": {}}}}, {"tool_spec": {"type": "cortex_analyst_text_to_sql", "name": "ReleasedSalesAnalyst", "description": "Answer sales questions using only the released, hash-guarded daily sales semantic view. Group by release_version and requested dimensions. Empty data is unavailable, not zero."}}], "tool_resources": {"DiscoverReleasedProduct": {"type": "procedure", "identifier": "HACKATHON_D2K_PREWORK.L2P_CONSUMER.DISCOVER_RELEASED_PRODUCT", "execution_environment": {"type": "warehouse", "warehouse": "DEFAULT_WH"}}, "RankCustomersBySales": {"type": "procedure", "identifier": "HACKATHON_D2K_PREWORK.L2P_CONSUMER.RANK_CUSTOMERS_BY_SALES", "execution_environment": {"type": "warehouse", "warehouse": "DEFAULT_WH"}}, "CustomerSalesDetail": {"type": "procedure", "identifier": "HACKATHON_D2K_PREWORK.L2P_CONSUMER.CUSTOMER_SALES_DETAIL", "execution_environment": {"type": "warehouse", "warehouse": "DEFAULT_WH"}}, "VerifyReleasedContract": {"type": "procedure", "identifier": "HACKATHON_D2K_PREWORK.L2P_CONSUMER.VERIFY_RELEASED_CONTRACT", "execution_environment": {"type": "warehouse", "warehouse": "DEFAULT_WH"}}, "ReleasedSalesAnalyst": {"semantic_view": "HACKATHON_D2K_PREWORK.L2P_CONSUMER.DAILY_SALES_SEMANTIC", "execution_environment": {"type": "warehouse", "warehouse": "DEFAULT_WH"}}}}$$;